solutionCodeJson.code:
// Reference solution
function weeklyPlan(start, items) {
  const t0 = Date.parse(`${start}T00:00:00Z`);
  return items.map((it, i) => ({ week: i + 1, due: new Date(t0 + (i + 1) * 7 * 86400000 - 86400000).toISOString().slice(0, 10), item: it }));
}
